As I have so many items, looking at the ICCs of all of them in one plot is not making any sense, So I need to plot 50 items in one plot,

info_char_plot=function(fit_object, plot_type)
{
  nplots=fit_object@Data$nitems %/% 50
  ll=seq(1, to = nplots*50+1, by=50)
  if(plot_type=="IIC")
  {

    for(i in 1:(nplots+1)){
    p=plot(fit_object, type = 'infotrace',which.items=ll[i]:min(50*i, fit_object@Data$nitems), auto.key=FALSE, main="Item Information Curves",
           panel=function(...) {
             panel.xyplot(...)
             panel.abline(v=c(-3,3), col="red", lwd=1)
           })
    print(p)
    }
  }

  else if(plot_type=="TIF")
  {
    Theta <- matrix(seq(-4,4, by = .01))
    TI <- 0
    for(i in 1:dim(fit_object@Data$data)[2]){
      TI <- TI + iteminfo(extract.item(fit_object, i), Theta)
    }
    plot(Theta, TI, type = 'l',xlab= 'Ability', ylab = ' Test Information Curves', las = 1, col="red", main="Test Information Curve")
  }
  else if(plot_type=="ICC")
  {
    for(i in 1:(nplots+1)){
      p=plot(fit_object, type = 'trace',which.items=ll[i]:min(50*i, fit_object@Data$nitems), auto.key = T,lwd = 5 , main="Item Characteristics Curves",
         panel=function(...) {
           panel.xyplot(...)
           panel.abline(v=c(-3,3), col="red", lwd=1)}
    )
    print(p)
    }

  }

}

